/// Storage selection at the inactive facade boundary.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum SyncStorageProfile {
    LegacyDefault,
    ExperimentalLocal,
}

/// Explicit paths for one already-enrolled local runtime.
///
/// No path is inspected for `LegacyDefault`.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct SyncRuntimeOpenRequest {
    pub profile: SyncStorageProfile,
    pub graph_root: PathBuf,
    pub enrollment_root: PathBuf,
    pub archive_root: PathBuf,
    pub receipt_root: PathBuf,
    pub database_path: PathBuf,
    pub application_runtime_root: PathBuf,
    pub migration_backup_root: PathBuf,
    pub provider_root: PathBuf,
    pub provider_journal_root: PathBuf,
}

/// Every caller-provided identity bound into one explicit local activation.
///
/// The public API never generates these values: callers persist them alongside
/// the activation request and pass the same values again to resume an
/// interrupted `ShadowImport` or `VerifiedLocal` attempt.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct SyncLocalActivationIdentities {
    pub workspace_id: WorkspaceId,
    pub lineage_digest: LineageDigest,
    pub catalog_document_id: DocumentId,
    pub endpoint_id: ProjectionEndpointId,
    pub device_id: DeviceId,
    pub preparation_id: Uuid,
    pub session_id: SessionId,
}

/// Explicit opt-in input for the bounded local sparse-oplog activation path.
///
/// `archive_root` must be exactly `<graph>/.tine-sync/v2`: it is the only
/// activation artifact permitted inside the graph. Every other supplied path
/// is checked before use and must remain outside the graph's canonical root.
/// No normal startup path constructs this request or calls the activation API.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct SyncLocalActivationRequest {
    pub graph_root: PathBuf,
    pub archive_root: PathBuf,
    pub enrollment_root: PathBuf,
    pub receipt_root: PathBuf,
    pub database_path: PathBuf,
    pub application_runtime_root: PathBuf,
    pub migration_backup_root: PathBuf,
    pub capture_root: PathBuf,
    pub preparation_root: PathBuf,
    pub provider_root: PathBuf,
    pub provider_journal_root: PathBuf,
    pub identities: SyncLocalActivationIdentities,
}

/// The only durable activation states the public composition can resume.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum SyncLocalActivationStage {
    Absent,
    ShadowImport,
    VerifiedLocal,
    LocalActive,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct SyncSharedEnrollmentDescriptor {
    encoded: Vec<u8>,
    pub workspace_id: WorkspaceId,
    pub lineage_digest: LineageDigest,
    pub catalog_document_id: DocumentId,
    pub descriptor_digest: String,
}

impl SyncSharedEnrollmentDescriptor {
    fn from_core(descriptor: SharedEnrollmentDescriptorV1) -> Result<Self, String> {
        Ok(Self {
            encoded: descriptor.encode().map_err(display)?,
            workspace_id: descriptor.workspace_id(),
            lineage_digest: descriptor.lineage_digest(),
            catalog_document_id: descriptor.catalog_document_id(),
            descriptor_digest: descriptor.digest().map_err(display)?.to_string(),
        })
    }

    fn decode(&self) -> Result<SharedEnrollmentDescriptorV1, String> {
        SharedEnrollmentDescriptorV1::decode(&self.encoded).map_err(display)
    }
}

pub fn inspect_shared_enrollment(
    provider_root: &Path,
) -> Result<Option<SyncSharedEnrollmentDescriptor>, String> {
    inspect_shared_provider_descriptor(provider_root)
        .map_err(display)?
        .map(|bytes| SharedEnrollmentDescriptorV1::decode(&bytes).map_err(display))
        .transpose()?
        .map(SyncSharedEnrollmentDescriptor::from_core)
        .transpose()
}

pub fn inspect_shared_enrollment_for_cold_discovery(
    provider_root: &Path,
) -> Result<Option<SyncSharedEnrollmentDescriptor>, String> {
    inspect_cold_shared_provider_descriptor(provider_root)
        .map_err(display)?
        .map(|bytes| SharedEnrollmentDescriptorV1::decode(&bytes).map_err(display))
        .transpose()?
        .map(SyncSharedEnrollmentDescriptor::from_core)
        .transpose()
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum SyncLocalActivationPhase {
    SourceCapture,
    BootstrapImportPreparation,
    ImmutablePublicationInstall,
    BackupProof,
    SqliteOpenBuild,
    ShadowReconstructionByteVerification,
    PromotionReceiptConfirmation,
    ReconciliationBaselineActorOpen,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum SyncBootstrapPreparationSubphase {
    SourceProtocol,
    OperationSpool,
    Partition,
    DetachedAuthoring,
    Sealing,
}

#[derive(Clone, Debug, Eq, PartialEq, Serialize)]
pub struct SyncBootstrapPreparationSummary {
    pub source_files: u64,
    pub source_bytes: u64,
    pub parser_nodes: u64,
    pub operations: u64,
    pub parts: u32,
    pub prepared_bytes: u64,
    pub source_protocol_micros: u64,
    pub operation_spool_micros: u64,
    pub partition_micros: u64,
    pub detached_authoring_micros: u64,
    pub sealing_micros: u64,
}

#[derive(Clone, Debug, Eq, PartialEq, Serialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum SyncLocalActivationProgress {
    Phase {
        phase: SyncLocalActivationPhase,
    },
    BootstrapPreparationSubphase {
        subphase: SyncBootstrapPreparationSubphase,
    },
    BootstrapDetachedAuthoring {
        completed: u32,
        total: u32,
    },
    BootstrapPreparationSummary {
        summary: SyncBootstrapPreparationSummary,
    },
}

impl SyncLocalActivationProgress {
    pub fn diagnostic_name(&self) -> String {
        match self {
            Self::Phase { phase } => phase.diagnostic_name().into(),
            Self::BootstrapPreparationSubphase { subphase } => format!(
                "bootstrap preparation: {}",
                match subphase {
                    SyncBootstrapPreparationSubphase::SourceProtocol => "source protocol",
                    SyncBootstrapPreparationSubphase::OperationSpool => "operation spool",
                    SyncBootstrapPreparationSubphase::Partition => "partition",
                    SyncBootstrapPreparationSubphase::DetachedAuthoring => "detached authoring",
                    SyncBootstrapPreparationSubphase::Sealing => "sealing",
                }
            ),
            Self::BootstrapDetachedAuthoring { completed, total } => {
                format!("bootstrap preparation: detached authoring {completed}/{total} parts")
            }
            Self::BootstrapPreparationSummary { summary } => format!(
                "bootstrap preparation complete: source_files={}, source_bytes={}, parser_nodes={}, operations={}, parts={}, prepared_bytes={}, durations_us=source_protocol:{},operation_spool:{},partition:{},detached_authoring:{},sealing:{}",
                summary.source_files,
                summary.source_bytes,
                summary.parser_nodes,
                summary.operations,
                summary.parts,
                summary.prepared_bytes,
                summary.source_protocol_micros,
                summary.operation_spool_micros,
                summary.partition_micros,
                summary.detached_authoring_micros,
                summary.sealing_micros,
            ),
        }
    }
}

impl From<BootstrapPreparationSubphase> for SyncBootstrapPreparationSubphase {
    fn from(subphase: BootstrapPreparationSubphase) -> Self {
        match subphase {
            BootstrapPreparationSubphase::SourceProtocol => Self::SourceProtocol,
            BootstrapPreparationSubphase::OperationSpool => Self::OperationSpool,
            BootstrapPreparationSubphase::Partition => Self::Partition,
            BootstrapPreparationSubphase::DetachedAuthoring => Self::DetachedAuthoring,
            BootstrapPreparationSubphase::Sealing => Self::Sealing,
        }
    }
}

impl From<BootstrapPreparationSummary> for SyncBootstrapPreparationSummary {
    fn from(summary: BootstrapPreparationSummary) -> Self {
        Self {
            source_files: summary.source_files,
            source_bytes: summary.source_bytes,
            parser_nodes: summary.parser_nodes,
            operations: summary.operations,
            parts: summary.parts,
            prepared_bytes: summary.prepared_bytes,
            source_protocol_micros: summary.source_protocol_micros,
            operation_spool_micros: summary.operation_spool_micros,
            partition_micros: summary.partition_micros,
            detached_authoring_micros: summary.detached_authoring_micros,
            sealing_micros: summary.sealing_micros,
        }
    }
}

impl From<BootstrapPreparationProgress> for SyncLocalActivationProgress {
    fn from(progress: BootstrapPreparationProgress) -> Self {
        match progress {
            BootstrapPreparationProgress::Subphase(subphase) => {
                Self::BootstrapPreparationSubphase {
                    subphase: subphase.into(),
                }
            }
            BootstrapPreparationProgress::DetachedAuthoring { completed, total } => {
                Self::BootstrapDetachedAuthoring { completed, total }
            }
            BootstrapPreparationProgress::Summary(summary) => Self::BootstrapPreparationSummary {
                summary: summary.into(),
            },
        }
    }
}

impl SyncLocalActivationPhase {
    pub const fn diagnostic_name(self) -> &'static str {
        match self {
            Self::SourceCapture => "source capture",
            Self::BootstrapImportPreparation => "bootstrap import preparation",
            Self::ImmutablePublicationInstall => "immutable publication/install",
            Self::BackupProof => "backup proof",
            Self::SqliteOpenBuild => "SQLite open/build",
            Self::ShadowReconstructionByteVerification => "shadow reconstruction/byte verification",
            Self::PromotionReceiptConfirmation => "promotion/aggregate authority confirmation",
            Self::ReconciliationBaselineActorOpen => "reconciliation baseline and actor open",
        }
    }
}

/// Typed result of an explicit local activation/resume attempt.
///
/// `Retryable` always reports the durable lifecycle last observed after the
/// failure; `Blocked` preserves the enrollment's durable reason code. A handle
/// is returned only for `Active`, after bootstrap, backup, shadow proof,
/// `VerifiedLocal`, promotion, SQLite proof, and reconciliation-baseline open
/// have all completed.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum SyncLocalActivationStatus {
    Active,
    Retryable {
        durable_stage: SyncLocalActivationStage,
        detail: String,
    },
    Blocked {
        reason_code: String,
    },
    LegacyV1Refused,
    UnsupportedOrIncompatible(SyncRuntimeComponent),
    CorruptOrUnreadable(SyncRuntimeComponent),
    AmbiguousOrForeignResidue(SyncAmbiguousEvidence),
}

/// Activation result, split from the retained runtime capability so callers
/// can persist or display failures without accidentally acquiring authority.
pub struct SyncLocalActivationResult {
    pub status: SyncLocalActivationStatus,
    pub handle: Option<SyncRuntimeHandle>,
}

impl fmt::Debug for SyncLocalActivationResult {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("SyncLocalActivationResult")
            .field("status", &self.status)
            .field("has_handle", &self.handle.is_some())
            .finish()
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum SyncRuntimeComponent {
    Enrollment,
    Archive,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum SyncNonActiveStage {
    ShadowImport,
    VerifiedLocal,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum SyncAmbiguousEvidence {
    EnrollmentResidue,
    EnrollmentNamespace,
    EnrollmentGraphBinding,
    ArchiveResidue,
    ArchiveNamespace,
    ArchiveBinding,
    ActiveArchiveMismatch,
}

/// Result of startup discovery and, only for a valid active result, actor open.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum SyncRuntimeOpenStatus {
    LegacyDefault,
    Absent,
    ExistingNonActive(SyncNonActiveStage),
    Blocked { reason_code: String },
    UnsupportedOrIncompatible(SyncRuntimeComponent),
    CorruptOrUnreadable(SyncRuntimeComponent),
    AmbiguousOrForeignResidue(SyncAmbiguousEvidence),
    Active,
    OpenRefused { detail: String },
}

/// Startup returns typed status separately from the optional channel handle.
pub struct SyncRuntimeOpenResult {
    pub status: SyncRuntimeOpenStatus,
    pub handle: Option<SyncRuntimeHandle>,
}

impl fmt::Debug for SyncRuntimeOpenResult {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("SyncRuntimeOpenResult")
            .field("status", &self.status)
            .field("has_handle", &self.handle.is_some())
            .finish()
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum SyncWatcherObservation {
    ManagedPath(ManagedPath),
    UnknownPath,
    NotifyError,
    RescanRequired,
}

impl SyncWatcherObservation {
    pub fn managed_path(path: impl Into<String>) -> Result<Self, SyncRuntimeRequestError> {
        ManagedPath::parse(path)
            .map(Self::ManagedPath)
            .map_err(|error| SyncRuntimeRequestError::InvalidRequest(error.to_string()))
    }

    fn retained_path_bytes(&self) -> usize {
        match self {
            Self::ManagedPath(path) => path.as_str().len(),
            Self::UnknownPath | Self::NotifyError | Self::RescanRequired => 0,
        }
    }

    fn into_core(self) -> WatcherObservation {
        match self {
            Self::ManagedPath(path) => WatcherObservation::ManagedPath(path),
            Self::UnknownPath => WatcherObservation::UnknownPath,
            Self::NotifyError => WatcherObservation::NotifyError,
            Self::RescanRequired => WatcherObservation::RescanRequired,
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum SyncRuntimeRecovery {
    FirstPromotion,
    ResumedOwnUnsafe,
    AdoptedSafeHandoff,
    TookOverCrashedUnsafe,
}

/// Ordered startup phases for an existing managed-storage runtime.
///
/// These are diagnostics only. They neither authorize a timeout fallback nor
/// expose a handle before the complete existing recovery path succeeds.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum SyncRuntimeOpenPhase {
    RetainingGraph,
    DiscoveringEnrollment,
    OpeningActorGraph,
    RevalidatingEnrollment,
    OpeningEnrollment,
    OpeningProjectionReceipts,
    OpeningReconciliationBaseline,
    RecoveringPromotedRuntime,
    AssemblingActor,
}

/// Content-free detail for a debug-enabled promoted-runtime recovery.  It is
/// observational only: no field grants recovery, scan, or mutation authority.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct SyncRuntimeRecoveryDiagnostics {
    pub recovery: &'static str,
    pub retention_plan: &'static str,
    pub retained_run_count: usize,
    pub resume_candidate: &'static str,
    pub detached_bootstrap_reconstruction: bool,
    pub full_bootstrap_replay: bool,
    pub manifest_count: usize,
    pub manifest_enumeration: Duration,
    pub resume_selection: Duration,
    pub bootstrap_reconstruction: Option<Duration>,
    pub engine_open: Duration,
    pub sqlite_open: Duration,
    pub tail_construction: Duration,
    pub total: Duration,
    pub projection_recovery: &'static str,
    pub projection_reason: String,
    pub projection_sidecar_shape: Duration,
    pub projection_checkpoint_authentication: Duration,
    pub projection_read_only_open: Duration,
    pub projection_schema_and_claim: Duration,
    pub projection_structural_validation: Duration,
    pub projection_materialization_stamp: Duration,
    pub projection_forensics_preservation: Duration,
    pub projection_rebuild: Duration,
    pub projection_applied_batches: usize,
    pub projection_bulk_pages_materialized: usize,
    pub projection_ancestry_full_scans: usize,
    pub prepare_replay: Duration,
    pub predecessor_restore: Duration,
    pub bootstrap_part_replay: Duration,
    pub archived_tail_replay: Duration,
    pub finish_replay: Duration,
    pub bootstrap_parts_replayed: usize,
    pub archived_manifests_offered: usize,
    pub archived_manifests_replayed: usize,
    pub resume_adopted: bool,
    pub resume_refused: bool,
    pub replay_base_generation: u64,
    pub live_history_generation: u64,
    pub replayed_generations: u64,
}

fn map_promoted_runtime_recovery_diagnostics(
    value: PromotedRuntimeRecoveryDiagnostics,
) -> SyncRuntimeRecoveryDiagnostics {
    SyncRuntimeRecoveryDiagnostics {
        recovery: value.recovery,
        retention_plan: value.retention_plan,
        retained_run_count: value.retained_run_count,
        resume_candidate: value.resume_candidate,
        detached_bootstrap_reconstruction: value.detached_bootstrap_reconstruction,
        full_bootstrap_replay: value.full_bootstrap_replay,
        manifest_count: value.manifest_count,
        manifest_enumeration: value.manifest_enumeration,
        resume_selection: value.resume_selection,
        bootstrap_reconstruction: value.bootstrap_reconstruction,
        engine_open: value.engine_open,
        sqlite_open: value.sqlite_open,
        tail_construction: value.tail_construction,
        total: value.total,
        projection_recovery: value.projection.recovery,
        projection_reason: value.projection.reason.clone(),
        projection_sidecar_shape: value.projection.sidecar_shape,
        projection_checkpoint_authentication: value.projection.checkpoint_authentication,
        projection_read_only_open: value.projection.read_only_open,
        projection_schema_and_claim: value.projection.schema_and_claim,
        projection_structural_validation: value.projection.structural_validation,
        projection_materialization_stamp: value.projection.materialization_stamp,
        projection_forensics_preservation: value.projection.forensics_preservation,
        projection_rebuild: value.projection.rebuild,
        projection_applied_batches: value.projection.applied_batches,
        projection_bulk_pages_materialized: value.projection.bulk_pages_materialized,
        projection_ancestry_full_scans: value.projection.ancestry_full_scans,
        prepare_replay: value.engine_stages.prepare_replay,
        predecessor_restore: value.engine_stages.predecessor_restore,
        bootstrap_part_replay: value.engine_stages.bootstrap_part_replay,
        archived_tail_replay: value.engine_stages.archived_tail_replay,
        finish_replay: value.engine_stages.finish_replay,
        bootstrap_parts_replayed: value.engine_stages.bootstrap_parts_replayed,
        archived_manifests_offered: value.engine_stages.archived_manifests_offered,
        archived_manifests_replayed: value.engine_stages.archived_manifests_replayed,
        resume_adopted: value.resume_adopted,
        resume_refused: value.resume_refused,
        replay_base_generation: value.replay_base_generation,
        live_history_generation: value.live_history_generation,
        replayed_generations: value.replayed_generations,
    }
}

