    #[test]
    fn accepted_ordinary_manifest_loss_without_local_archive_blocks() {
        let fixture = make_shared_fixture("provider-ordinary-manifest-archive-loss", 0xbb28);
        let _descriptor = activate_and_prepare_shared(&fixture);
        let handle = active_handle(SyncRuntimeHandle::open(reopen_request(&fixture.request)));
        settle_shared_provider(&handle);
        let (batch_id, ..) = submit_shared_page(
            &handle,
            0xbb2a,
            "Ordinary Manifest Archive Loss",
            "notes/ordinary-manifest-archive-loss.md",
            "ordinary archive evidence remains required",
        );
        publish_shared_batch(&handle, &fixture, batch_id);
        settle_shared_provider(&handle);

        let relative = format!("manifests/{batch_id}.manifest");
        let manifest = fixture.request.provider_root.join("outbox").join(&relative);
        let (recovery_link, recovery_blob, ..) =
            provider_manifest_recovery_paths(&fixture, batch_id);
        let local_manifest = fixture
            .request
            .archive_root
            .join("batches")
            .join(format!("{batch_id}.manifest"));
        assert!(
            manifest.is_file()
                && recovery_link.is_file()
                && recovery_blob.is_file()
                && local_manifest.is_file()
        );
        fs::remove_file(&manifest).unwrap();
        fs::remove_file(&recovery_link).unwrap();
        fs::remove_file(&recovery_blob).unwrap();
        fs::remove_file(&local_manifest).unwrap();

        handle
            .observe_provider_paths(vec![relative], false)
            .unwrap();
        let mut blocked = None;
        for _ in 0..32 {
            match handle.tick().unwrap() {
                SyncRuntimeTick::RecoveryBlocked(detail) => {
                    blocked = Some(detail);
                    break;
                }
                SyncRuntimeTick::Recovering | SyncRuntimeTick::Idle => {}
                other => panic!("ordinary accepted archive loss did not fail closed: {other:?}"),
            }
        }
        assert!(
            blocked.as_ref().is_some_and(|detail| {
                detail.contains("accepted provider manifest is absent")
                    || detail.contains("and its local archive are absent")
            }),
            "ordinary accepted archive loss did not retain its exact blocked reason: {blocked:?}"
        );
        assert!(
            !manifest.exists(),
            "ordinary accepted archive loss was treated as manifestless authority"
        );
        assert!(
            handle.clean_shutdown().is_err(),
            "ordinary accepted archive loss reached Safe"
        );
    }

    #[test]
    fn restart_audit_finds_non_tip_accepted_manifest_loss_and_repairs_reappearance() {
        let (author, receiver, author_handle, receiver_handle) =
            joined_shared_pair("provider-nontip-restart-audit", 0xbb29);
        let (first_batch, page_id, ..) = submit_shared_page(
            &author_handle,
            0xbb40,
            "Non-tip Restart Audit",
            "notes/non-tip-restart-audit.md",
            "accepted batch A",
        );
        publish_shared_batch(&author_handle, &author, first_batch);
        let delivered = copy_provider_batch(
            &author,
            &receiver,
            first_batch,
            ProviderBatchDelivery::Complete,
        );
        receiver_handle
            .observe_provider_paths(delivered, false)
            .unwrap();
        settle_shared_provider(&receiver_handle);
        let second_batch = submit_durable(
            &author_handle,
            vec![SemanticOperation::SetPagePreamble {
                page_id,
                preamble: Some("accepted batch B".into()),
            }],
        );
        publish_shared_batch(&author_handle, &author, second_batch);
        let delivered = copy_provider_batch(
            &author,
            &receiver,
            second_batch,
            ProviderBatchDelivery::Complete,
        );
        receiver_handle
            .observe_provider_paths(delivered, false)
            .unwrap();
        settle_shared_provider(&receiver_handle);
        let third_batch = submit_durable(
            &author_handle,
            vec![SemanticOperation::SetPagePreamble {
                page_id,
                preamble: Some("accepted batch C".into()),
            }],
        );
        publish_shared_batch(&author_handle, &author, third_batch);
        let delivered = copy_provider_batch(
            &author,
            &receiver,
            third_batch,
            ProviderBatchDelivery::Complete,
        );
        receiver_handle
            .observe_provider_paths(delivered, false)
            .unwrap();
        settle_shared_provider(&receiver_handle);
        assert!(matches!(
            receiver_handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));

        let relative = format!("manifests/{first_batch}.manifest");
        let provider_manifest = receiver
            .request
            .provider_root
            .join("outbox")
            .join(&relative);
        let (recovery_link, recovery_blob, ..) =
            provider_manifest_recovery_paths(&receiver, first_batch);
        let local_manifest = receiver
            .request
            .archive_root
            .join("batches")
            .join(format!("{first_batch}.manifest"));
        let local_manifest_bytes = fs::read(&local_manifest).unwrap();
        let first_manifest = OperationBatch::decode(&local_manifest_bytes).unwrap();
        let first_provider_objects = first_manifest
            .required_objects()
            .iter()
            .map(|object| {
                receiver
                    .request
                    .provider_root
                    .join(format!("outbox/objects/{}.object", object.content_digest()))
            })
            .collect::<Vec<_>>();
        assert!(first_provider_objects.iter().all(|path| path.is_file()));
        assert!(receiver
            .request
            .provider_root
            .join(format!("outbox/manifests/{third_batch}.manifest"))
            .is_file());
        fs::remove_file(&provider_manifest).unwrap();
        fs::remove_file(&recovery_link).unwrap();
        fs::remove_file(&recovery_blob).unwrap();
        fs::remove_file(&local_manifest).unwrap();

        let refused = active_handle(SyncRuntimeHandle::open(reopen_request(&receiver.request)));
        let mut blocked = None;
        for _ in 0..4_096 {
            match refused.tick_provider_for_test().unwrap() {
                SyncRuntimeTick::RecoveryBlocked(detail) => {
                    blocked = Some(detail);
                    break;
                }
                SyncRuntimeTick::Idle | SyncRuntimeTick::Recovering => {}
                other => panic!("accepted-manifest revalidation returned {other:?}"),
            }
        }
        assert!(
            blocked.as_ref().is_some_and(|detail| {
                detail.contains("accepted provider manifest is absent")
                    || detail.contains("and its local archive are absent")
            }),
            "bounded restart revalidation did not fail closed on missing accepted non-tip authority: {blocked:?}"
        );
        drop(refused);
        assert!(first_provider_objects.iter().all(|path| path.is_file()));
        fs::write(&local_manifest, local_manifest_bytes).unwrap();

        PROVIDER_ACCEPTED_AUDIT_LIMIT_OVERRIDES
            .lock()
            .unwrap()
            .insert(receiver.request.identities.workspace_id, 1);
        let restarted = active_handle(SyncRuntimeHandle::open(reopen_request(&receiver.request)));
        let mut recovering_pages = 0;
        let mut repaired = false;
        for _ in 0..4_096 {
            match restarted.tick_provider_for_test().unwrap() {
                SyncRuntimeTick::Recovering => recovering_pages += 1,
                SyncRuntimeTick::Idle => {}
                other => panic!("restart accepted-manifest audit failed unexpectedly: {other:?}"),
            }
            if provider_manifest.is_file() && recovery_link.is_file() && recovery_blob.is_file() {
                repaired = true;
                break;
            }
        }
        assert!(
            recovering_pages >= 2,
            "accepted-manifest restart audit did not advance in bounded pages"
        );
        assert!(
            repaired,
            "restart audit did not republish recoverable non-tip authority"
        );
        settle_shared_provider(&restarted);
        PROVIDER_ACCEPTED_AUDIT_LIMIT_OVERRIDES
            .lock()
            .unwrap()
            .remove(&receiver.request.identities.workspace_id);
        assert!(
            recovery_link.is_file() && recovery_blob.is_file(),
            "local manifest recovery did not repair provider authority"
        );
        assert!(matches!(
            restarted.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(snapshot)) if snapshot.provider_pending == 0
        ));
        assert!(matches!(
            author_handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
    }

